INSERT INTO rules (id, text) VALUES (0, 'Furnace 1 and Furnace 2 cannot heat at the same time');
INSERT INTO rules (id, text) VALUES (1, 'Furnace 1 and Furnace 3 cannot heat at the same time');
INSERT INTO rules (id, text) VALUES (2, 'Furnace 2 and Furnace 3 cannot heat at the same time');
INSERT INTO rules (id, text) VALUES (3, 'Furnace 4 and Furnace 6 cannot heat at the same time');
INSERT INTO rules (id, text) VALUES (4, 'Furnace 4 and Furnace 5 cannot heat at the same time');
INSERT INTO rules (id, text) VALUES (5, 'Furnace 5 and Furnace 6 cannot heat at the same time');
INSERT INTO rules (id, text) VALUES (6, 'It takes one hour to load a furnace before heating');
INSERT INTO rules (id, text) VALUES (7, 'It takes one hour to unload a furnace after cooling');
INSERT INTO rules (id, text) VALUES (8, 'Cooling system 1 need to run during both heating and cooling for furnace 1, furnace 2 and furnace 3');
INSERT INTO rules (id, text) VALUES (9, 'Cooling system 2 needs to run during both heating and cooling for furnace 4, furnace 5 and furnace 6');
INSERT INTO rules (id, text) VALUES (10, 'Vacuum system 01 needs to run during both heating and cooling for furnace 3');
INSERT INTO rules (id, text) VALUES (11, 'Vacuum system 02 needs to run during both heating and cooling for furnace 4');
INSERT INTO rules (id, text) VALUES (12, 'Run coating line as much as possible');
INSERT INTO rules (id, text) VALUES (13, 'Coating line needs 200A electricity during first 2 hours, then 100A for continuous running. If it stops, then it has to heat up again with 200A for 2 hours');
